import { useRef, useState } from 'react'
import { formatarData } from '../../regras/datas.js'

/** Backup, importação e redefinição do estado salvo no navegador. */
export default function AdminDados({ dados, totais }) {
  const arquivo = useRef(null)
  const [msg, setMsg] = useState('')

  function exportar() {
    const blob = new Blob([dados.exportar()], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url; a.download = `lombada-backup-${new Date().toISOString().slice(0, 10)}.json`; a.click()
    URL.revokeObjectURL(url)
    setMsg('Backup exportado.')
  }

  async function importar(e) {
    const f = e.target.files?.[0]
    if (!f) return
    try {
      dados.importar(await f.text())
      setMsg(`Importado de ${f.name}.`)
    } catch (err) {
      setMsg(`Não importei: ${err.message}`)
    }
    e.target.value = ''
  }

  function redefinir() {
    if (!confirm('Apagar tudo o que foi salvo neste navegador e voltar aos dados de exemplo?')) return
    dados.redefinir()
    setMsg('Dados de exemplo restaurados.')
  }

  const hora = dados.salvoEm ? new Date(dados.salvoEm).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) : null

  return (
    <div className="grid gap-6 max-w-2xl">
      <div className="bg-areia p-6">
        <p className="text-[11px] font-extrabold uppercase tracking-[.1em] text-mudo">Onde os dados estão</p>
        <p className="mt-2 text-[14.5px]">
          Nesta fase, tudo fica salvo <b>neste navegador</b> (localStorage). Outro navegador ou outra pessoa não vê. Para levar os dados adiante, exporte o backup.
        </p>
        <p className="text-[13px] text-mudo mt-2">
          {dados.salvoEm ? `Último salvamento hoje às ${hora} (${formatarData(dados.salvoEm)}).` : 'Nada salvo ainda.'}
          {' '}{totais.autores} autores · {totais.leitores} leitores · {totais.acoes} ações · {totais.modelos} modelos · {totais.oportunidades} oportunidades.
        </p>
      </div>

      <div className="grid sm:grid-cols-3 gap-4">
        <div className="bg-areia p-5 grid content-between gap-4">
          <div><p className="font-extrabold">Exportar backup</p><p className="text-[13px] text-apoio mt-1">Um arquivo JSON com autores, leitores, ações, modelos e oportunidades.</p></div>
          <button onClick={exportar} className="btn-preto justify-self-start">Exportar</button>
        </div>
        <div className="bg-areia p-5 grid content-between gap-4">
          <div><p className="font-extrabold">Importar backup</p><p className="text-[13px] text-apoio mt-1">Substitui o que está neste navegador pelo conteúdo do arquivo.</p></div>
          <button onClick={() => arquivo.current?.click()} className="btn-preto justify-self-start">Escolher arquivo</button>
          <input ref={arquivo} type="file" accept="application/json" onChange={importar} className="hidden" />
        </div>
        <div className="bg-areia p-5 grid content-between gap-4">
          <div><p className="font-extrabold">Redefinir</p><p className="text-[13px] text-apoio mt-1">Apaga o que foi salvo e volta aos dados de exemplo do arquivo.</p></div>
          <button onClick={redefinir} className="btn bg-alerta text-white corte-btn justify-self-start">Redefinir</button>
        </div>
      </div>

      {msg && <p className="text-[13.5px] font-semibold">{msg}</p>}
    </div>
  )
}
