import { useState } from 'react'
import { FASES, NOME_FASE } from '../../regras/fase.js'
import { formatarTempo } from '../../regras/datas.js'
import { classeInput, Campo, Escolha, EscolhaMultipla } from '../../componentes/campos.jsx'
import { Lista, Formulario, novoId } from './ListaEditavel.jsx'
import { CONDICOES } from '../../regras/personalizacao.js'
import { OBJETIVOS } from '../../dados/opcoes.js'

const OPCOES_FASE = Object.values(FASES).map((f) => ({ valor: f, rotulo: NOME_FASE[f] }))

function acaoVazia(fase) {
  return { id: novoId('acao'), fase, ordem: 1, semana: 1, titulo: '', descricao: '', tempoMinutos: 30, modeloIds: [], aula: null, requer: [], objetivos: [] }
}

export default function AdminAcoes({ acoes, modelos, onSalvar, onExcluir }) {
  const [faseFiltro, setFaseFiltro] = useState(FASES.CONSTRUCAO)
  const [edicao, setEdicao] = useState(null) // objeto em edição ou null

  const daFase = acoes.filter((a) => a.fase === faseFiltro).sort((a, b) => a.ordem - b.ordem)
  const modelosBase = modelos.filter((m) => !m.variaDe)
  const set = (campo, valor) => setEdicao((e) => ({ ...e, [campo]: valor }))
  const setAula = (campo, valor) => setEdicao((e) => {
    const aula = { ...(e.aula || {}), [campo]: valor }
    const vazia = !aula.modulo && !aula.nome && !aula.url
    return { ...e, aula: vazia ? null : aula }
  })
  const existente = edicao && acoes.some((a) => a.id === edicao.id)

  return (
    <div className="grid grid-cols-1 lg:grid-cols-[1fr_1.2fr] gap-8">
      <div>
        <div className="mb-4">
          <Escolha valor={faseFiltro} onChange={(v) => { setFaseFiltro(v); setEdicao(null) }} opcoes={OPCOES_FASE} />
        </div>
        <Lista
          itens={daFase}
          chave={(a) => a.id}
          selecionadoId={edicao?.id}
          onSelecionar={(id) => setEdicao({ ...acoes.find((a) => a.id === id) })}
          cabecalho={`${daFase.length} ações na fase ${NOME_FASE[faseFiltro]}`}
          rotuloNovo="Nova ação"
          onNovo={() => setEdicao(acaoVazia(faseFiltro, daFase.length + 1))}
          renderLinha={(a) => (
            <div className="flex items-baseline gap-3">
              <span className="text-mudo tabular-nums w-4">{a.ordem}</span>
              <span className="flex-1 text-tinta">{a.titulo}</span>
              <span className="text-mudo shrink-0">{a.aula ? `M${a.aula.modulo} · ` : ''}{formatarTempo(a.tempoMinutos)}{a.modeloIds.length ? ` · ${a.modeloIds.length} modelo${a.modeloIds.length > 1 ? 's' : ''}` : ''}</span>
            </div>
          )}
        />
      </div>

      {edicao ? (
        <Formulario
          titulo={existente ? 'Editar ação' : 'Nova ação'}
          podeSalvar={Boolean(edicao.titulo.trim())}
          onSalvar={() => { onSalvar({ ...edicao, ordem: Number(edicao.ordem) || 1, semana: Number(edicao.semana) || 1, tempoMinutos: Number(edicao.tempoMinutos) || 0 }); setEdicao(null) }}
          onCancelar={() => setEdicao(null)}
          onExcluir={existente ? () => { if (confirm(`Excluir a ação "${edicao.titulo}"?`)) { onExcluir(edicao.id); setEdicao(null) } } : null}
        >
          <Campo rotulo="Fase">
            <Escolha valor={edicao.fase} onChange={(v) => set('fase', v)} opcoes={OPCOES_FASE} />
          </Campo>
          <div className="grid grid-cols-3 gap-4">
            <Campo rotulo="Ordem" ajuda="Sequência dentro da fase">
              <input type="number" min="1" className={classeInput} value={edicao.ordem} onChange={(e) => set('ordem', e.target.value)} />
            </Campo>
            <Campo rotulo="Semana" ajuda="Semana sugerida">
              <input type="number" min="1" className={classeInput} value={edicao.semana} onChange={(e) => set('semana', e.target.value)} />
            </Campo>
            <Campo rotulo="Tempo (min)">
              <input type="number" min="5" step="5" className={classeInput} value={edicao.tempoMinutos} onChange={(e) => set('tempoMinutos', e.target.value)} />
            </Campo>
          </div>
          <Campo rotulo="Título" ajuda="Comece com um verbo. Aceita {titulo_livro}, {primeiro_nome}, {genero}, {tema}, {publico_alvo|alternativa}, {cidade|alternativa}.">
            <input className={classeInput} value={edicao.titulo} onChange={(e) => set('titulo', e.target.value)} autoFocus />
          </Campo>
          <Campo rotulo="Descrição curta">
            <textarea className={classeInput + ' min-h-20'} value={edicao.descricao} onChange={(e) => set('descricao', e.target.value)} />
          </Campo>
          <div className="grid grid-cols-1 sm:grid-cols-[90px_1fr] gap-4">
            <Campo rotulo="Módulo" ajuda="Aula de origem">
              <input type="number" min="1" className={classeInput} value={edicao.aula?.modulo ?? ''} onChange={(e) => setAula('modulo', e.target.value ? Number(e.target.value) : '')} />
            </Campo>
            <Campo rotulo="Nome da aula" ajuda="Aparece como 'Assistir a aula · Módulo X · Nome'">
              <input className={classeInput} value={edicao.aula?.nome ?? ''} onChange={(e) => setAula('nome', e.target.value)} />
            </Campo>
          </div>
          <Campo rotulo="Link direto da aula (opcional)" ajuda="Sem link, o botão abre a área de membros do Método The Book Business na Hotmart.">
            <input className={classeInput} value={edicao.aula?.url ?? ''} onChange={(e) => setAula('url', e.target.value)} placeholder="https://hotmart.com/pt-br/club/..." />
          </Campo>
          <Campo rotulo="Condições (a ação só entra no plano se valerem)" ajuda="Ver regras/personalizacao.js">
            <EscolhaMultipla valores={edicao.requer || []} onChange={(v) => set('requer', v)} opcoes={Object.entries(CONDICOES).map(([k, c]) => ({ valor: k, rotulo: c.descricao }))} />
          </Campo>
          <Campo rotulo="Prioritária para o objetivo" ajuda="Sobe no plano de quem tem este objetivo">
            <EscolhaMultipla valores={edicao.objetivos || []} onChange={(v) => set('objetivos', v)} opcoes={OBJETIVOS} />
          </Campo>
          <Campo rotulo="Modelos de texto vinculados" ajuda="Até 2. Sem modelo, a ação é de execução. Variantes por gênero são escolhidas automaticamente.">
            <EscolhaMultipla
              valores={edicao.modeloIds}
              onChange={(v) => set('modeloIds', v.slice(-2))}
              opcoes={modelosBase.map((m) => ({ valor: m.id, rotulo: `${m.nome} (${m.angulo})` }))}
            />
          </Campo>
        </Formulario>
      ) : (
        <div className="text-sm text-mudo border-2 border-dashed border-fio p-6">
          Selecione uma ação para editar ou clique em "Nova ação".
        </div>
      )}
    </div>
  )
}
