import { useState } from 'react'
import { Link } from 'react-router-dom'
import Wordmark from '../componentes/Wordmark.jsx'
import AdminAutores from './admin/AdminAutores.jsx'
import AdminSugestoes from './admin/AdminSugestoes.jsx'
import AdminAcoes from './admin/AdminAcoes.jsx'
import AdminModelos from './admin/AdminModelos.jsx'
import AdminOportunidades from './admin/AdminOportunidades.jsx'
import AdminDados from './admin/AdminDados.jsx'
import AdminOperacao from './admin/AdminOperacao.jsx'
import AdminUso from './admin/AdminUso.jsx'

const ABAS = [
  { id: 'autores', rotulo: 'Autores' },
  { id: 'acoes', rotulo: 'Ações' },
  { id: 'modelos', rotulo: 'Modelos de texto' },
  { id: 'oportunidades', rotulo: 'Oportunidades' },
  { id: 'sugestoes', rotulo: 'Sugestões' },
  { id: 'uso', rotulo: 'Uso' },
  { id: 'operacao', rotulo: 'Operação' },
  { id: 'dados', rotulo: 'Dados' },
]

export default function Admin({ autores, leitores, acoes, modelos, oportunidades, dados, alterarAcesso, salvarAcao, excluirAcao, salvarModelo, excluirModelo, salvarOportunidade, excluirOportunidade, alterarCadastro, sugestoes = [], marcarSugestaoLida, gerarCodigo, definirCodigo, alterarEmail, codigos = {}, onSair, equipe, operacao, uso, alterarVagas, amazon = {} }) {
  const [aba, setAba] = useState('autores')

  return (
    <div className="min-h-screen">
      <div className="border-b-2 border-tinta">
        <div className="max-w-5xl mx-auto px-6 py-4 flex flex-wrap items-center justify-between gap-4">
          <span className="flex items-baseline gap-3">
            <Wordmark tamanho={24} />
            <span className="text-[11px] font-extrabold uppercase tracking-[.14em] text-mudo">Administrador</span>
          </span>
          <nav className="flex flex-wrap items-center gap-5">
            {ABAS.map((a) => (
              <button
                key={a.id}
                onClick={() => setAba(a.id)}
                className={'relative text-[13px] font-bold pb-1 hover:text-tinta ' + (aba === a.id ? 'text-tinta' : 'text-mudo')}
              >
                {a.rotulo}
                {aba === a.id && <i className="absolute left-0 right-0 -bottom-[2px] h-[4px] bg-ambar" style={{ clipPath: 'polygon(0 0, 100% 0, 88% 100%, 0 100%)' }} />}
              </button>
            ))}
            <span className="text-fio">|</span>
            <Link to="/" className="text-[13px] font-bold text-mudo hover:text-tinta">Área do autor ↗</Link>
            {equipe && <span className="text-[12px] text-mudo hidden sm:inline">{equipe}</span>}
            {onSair && <button onClick={onSair} className="btn-linha">Sair</button>}
          </nav>
        </div>
      </div>

      <main className="max-w-5xl mx-auto px-6 py-8">
        <h1 className="display text-[30px] mb-6">{ABAS.find((a) => a.id === aba)?.rotulo}</h1>
        {aba === 'autores' && <AdminAutores autores={autores} leitores={leitores} onAlterarAcesso={alterarAcesso} onAlterarCadastro={alterarCadastro} onGerarCodigo={gerarCodigo} onDefinirCodigo={definirCodigo} onAlterarEmail={alterarEmail} onAlterarVagas={alterarVagas} codigos={codigos} amazon={amazon} />}
        {aba === 'acoes' && <AdminAcoes acoes={acoes} modelos={modelos} onSalvar={salvarAcao} onExcluir={excluirAcao} />}
        {aba === 'modelos' && <AdminModelos modelos={modelos} autores={autores} onSalvar={salvarModelo} onExcluir={excluirModelo} />}
        {aba === 'uso' && <AdminUso uso={uso} autores={autores} />}
        {aba === 'operacao' && <AdminOperacao operacao={operacao} />}
        {aba === 'dados' && <AdminDados dados={dados} totais={{ autores: autores.length, leitores: leitores.length, acoes: acoes.length, modelos: modelos.length, oportunidades: oportunidades.length }} />}
        {aba === 'sugestoes' && <AdminSugestoes sugestoes={sugestoes} autores={autores} onMarcarLida={marcarSugestaoLida} />}
        {aba === 'oportunidades' && <AdminOportunidades oportunidades={oportunidades} onSalvar={salvarOportunidade} onExcluir={excluirOportunidade} />}
      </main>
    </div>
  )
}
