import { formatarData } from '../../regras/datas.js'

export default function AdminSugestoes({ sugestoes, autores, onMarcarLida }) {
  const lista = [...sugestoes].sort((a, b) => new Date(b.data) - new Date(a.data))
  const nome = (id) => autores.find((a) => a.id === id)?.nome || 'autor removido'
  const novas = lista.filter((s) => s.status !== 'lida').length
  if (lista.length === 0) return <p className="text-sm text-apoio">Nenhuma sugestão ainda. Os autores enviam pelo menu Sugestões.</p>
  return (
    <div>
      <p className="text-sm text-apoio mb-4">{lista.length} {lista.length === 1 ? 'sugestão' : 'sugestões'}{novas ? `, ${novas} ${novas === 1 ? 'nova' : 'novas'}` : ''}.</p>
      <ul className="grid gap-3">
        {lista.map((s) => (
          <li key={s.id} className={'px-5 py-4 border-2 ' + (s.status === 'lida' ? 'border-fio bg-white' : 'border-ambar bg-areia')}>
            <div className="flex flex-wrap items-baseline justify-between gap-2">
              <p className="text-[12px] font-extrabold">{nome(s.autorId)} <span className="text-mudo font-semibold">· {formatarData(s.data)}</span></p>
              {s.status !== 'lida' && <button onClick={() => onMarcarLida(s.id)} className="text-[12px] font-bold underline underline-offset-4">marcar como lida</button>}
            </div>
            <p className="text-[14px] mt-2 leading-relaxed">{s.texto}</p>
          </li>
        ))}
      </ul>
    </div>
  )
}
