import { useState } from 'react'
import { GENEROS } from '../../dados/exemplo.js'
import { diasAteOPrazo } from '../../regras/oportunidades.js'
import { formatarData } from '../../regras/datas.js'
import { classeInput, Campo, Select, EscolhaMultipla } from '../../componentes/campos.jsx'
import { Lista, Formulario, novoId } from './ListaEditavel.jsx'

const TIPOS = ['Edital', 'Prêmio literário', 'Feira', 'Antologia', 'Evento']

function oportunidadeVazia() {
  return { id: novoId('op'), tipo: 'Edital', nome: '', descricao: '', generos: [], prazo: '', link: '' }
}

export default function AdminOportunidades({ oportunidades, onSalvar, onExcluir }) {
  const [edicao, setEdicao] = useState(null)
  const set = (campo, valor) => setEdicao((e) => ({ ...e, [campo]: valor }))
  const existente = edicao && oportunidades.some((o) => o.id === edicao.id)

  const ordenadas = [...oportunidades].sort((a, b) => new Date(a.prazo) - new Date(b.prazo))
  const vencidas = ordenadas.filter((o) => diasAteOPrazo(o.prazo) < 0).length
  const todos = edicao && edicao.generos.length === GENEROS.length

  return (
    <div className="grid grid-cols-1 lg:grid-cols-[1fr_1.2fr] gap-8">
      <Lista
        itens={ordenadas}
        chave={(o) => o.id}
        selecionadoId={edicao?.id}
        onSelecionar={(id) => { const o = oportunidades.find((x) => x.id === id); setEdicao({ ...o, prazo: o.prazo.slice(0, 10) }) }}
        cabecalho={`${oportunidades.length} oportunidades${vencidas ? `, ${vencidas} vencida${vencidas > 1 ? 's' : ''}` : ''}`}
        rotuloNovo="Nova oportunidade"
        onNovo={() => setEdicao(oportunidadeVazia())}
        renderLinha={(o) => {
          const dias = diasAteOPrazo(o.prazo)
          return (
            <div className="flex items-baseline gap-3">
              <span className="text-xs uppercase tracking-wide text-mudo w-24 shrink-0">{o.tipo}</span>
              <span className={'flex-1 ' + (dias < 0 ? 'text-mudo line-through' : 'text-tinta')}>{o.nome}</span>
              <span className="text-mudo shrink-0 tabular-nums">{dias < 0 ? 'vencida' : formatarData(o.prazo)}</span>
            </div>
          )
        }}
      />

      {edicao ? (
        <Formulario
          titulo={existente ? 'Editar oportunidade' : 'Nova oportunidade'}
          podeSalvar={Boolean(edicao.nome.trim() && edicao.prazo && edicao.generos.length)}
          onSalvar={() => { onSalvar({ ...edicao, prazo: new Date(edicao.prazo + 'T12:00:00').toISOString() }); setEdicao(null) }}
          onCancelar={() => setEdicao(null)}
          onExcluir={existente ? () => { if (confirm(`Excluir "${edicao.nome}"?`)) { onExcluir(edicao.id); setEdicao(null) } } : null}
        >
          <div className="grid grid-cols-1 sm:grid-cols-[160px_1fr] gap-4">
            <Campo rotulo="Tipo"><Select valor={edicao.tipo} onChange={(v) => set('tipo', v)} opcoes={TIPOS} /></Campo>
            <Campo rotulo="Nome"><input className={classeInput} value={edicao.nome} onChange={(e) => set('nome', e.target.value)} autoFocus /></Campo>
          </div>
          <Campo rotulo="Descrição">
            <textarea className={classeInput + ' min-h-20'} value={edicao.descricao} onChange={(e) => set('descricao', e.target.value)} />
          </Campo>
          <Campo rotulo="Gêneros aos quais se aplica">
            <div className="mb-2">
              <button type="button" onClick={() => set('generos', todos ? [] : [...GENEROS])} className="text-xs text-mudo underline underline-offset-4 hover:text-tinta">
                {todos ? 'limpar todos' : 'marcar todos os gêneros'}
              </button>
            </div>
            <EscolhaMultipla valores={edicao.generos} onChange={(v) => set('generos', v)} opcoes={GENEROS} />
          </Campo>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <Campo rotulo="Data limite de inscrição">
              <input type="date" className={classeInput} value={edicao.prazo} onChange={(e) => set('prazo', e.target.value)} />
            </Campo>
            <Campo rotulo="Link">
              <input className={classeInput} value={edicao.link} onChange={(e) => set('link', e.target.value)} placeholder="https://" />
            </Campo>
          </div>
        </Formulario>
      ) : (
        <div className="text-sm text-mudo border-2 border-dashed border-fio p-6">
          Selecione uma oportunidade para editar ou clique em "Nova oportunidade".
        </div>
      )}
    </div>
  )
}
